(function(){
const ok=new Set(['everyday','date','team']);
const configs={
everyday:{k:'会話のあたらしいはじめかた',lead:'いま一緒にいる2～8人で、同じ質問、違う答え。きっと見つかる新たな魅力。',q:'最近、つい笑ってしまった出来事は？',s:[['/assets/lp-day-cafe.webp','友達とカフェ','最近、つい笑ってしまった出来事は？','友達'],['/assets/lp-family-talk.webp','家族の食卓','今の暮らしで、意外と気に入っている小さな習慣は？','家族'],['/assets/lp-team-break.webp','同僚の休憩時間','最近ハマっていること、または気になっていることは？','同僚'],['/assets/lp-day-trip.webp','キャンプの途中','次に会うときまでに、お互い試しておいたら面白そうなことは？','キャンプ'],['/assets/lp-weekend-two.webp','夫婦の休日','今日の会話の続きをするなら、次はどんなことを一緒に話してみたい？','夫婦'],['/assets/lp-izakaya-friends.webp','居酒屋の友人たち','最近、つい笑ってしまった出来事は？','居酒屋'],['/assets/lp-city-date.webp','デートの夜','最近、予定外だったけれど嬉しかったことは？','デート']]},
date:{k:'DATE, TOGETHER',lead:'初めて会う夜も、少し深く話したい夜も。気負わず、同じ質問を順番に。',q:'最近、予定外だったけれど嬉しかったことは？',s:[['/assets/lp-city-date.webp','街の夜、初対面','最近、予定外だったけれど嬉しかったことは？','初対面'],['/assets/lp-intimate-livingroom.webp','ゆっくり話す夜','最近、自分に「よくやった」と言いたいことは？','おうち'],['/assets/lp-home-party.webp','家で過ごす時間','これから、なんて呼んで欲しい？','集まり'],['/assets/lp-night-terrace.webp','夜景を眺めながら','いつか一緒に見てみたい景色や行ってみたい場所は？','夜景'],['/assets/lp-late-cafe.webp','夜のもう一問','意外な場面で、誰かや何かにときめいたことは？','カフェ']]},
team:{k:'TEAM, TOGETHER',lead:'同僚やイベントの初対面でも、スマホ1台。答えたくないときはパスできます。',q:'最近、仕事や学びで「面白い」と感じたことは？',s:[['/assets/lp-team-break.webp','チームの休憩','最近、仕事や学びで「面白い」と感じたことは？','同僚'],['/assets/lp-bar-first-meet.webp','初対面の集まり','これから、なんて呼んで欲しい？','交流会'],['/assets/lp-day-cafe.webp','イベントのあと','詳しくなりたいけれど、まだ時間を取れていないテーマは？','イベント'],['/assets/lp-day-trip.webp','チームの旅','最近、仕事とは別に時間を使っている興味は？','旅先'],['/assets/lp-team-workshop.webp','チームビルディング','最近、やり方を変えてよかった仕事の習慣は？','チームビルディング']]}};
const valid=v=>ok.has(v)?v:null;
function route(){let storage=null;try{storage=window.localStorage}catch(_){}return window.MingleExperienceRouting?.resolve({search:location.search,storage,now:Date.now()})||{experience:'everyday',source:'default'}}
function setup(){const picker=document.querySelector('.experience-picker');if(picker&&!picker.children.length){picker.innerHTML='<div><p class="eyebrow">CHOOSE YOUR MOMENT</p><p>使う場面を選ぶ</p></div><div class="experience-buttons"><button data-experience-choice="everyday" aria-pressed="false">いつもの時間</button><button data-experience-choice="date" aria-pressed="false">ふたりの夜</button><button data-experience-choice="team" aria-pressed="false">チームの時間</button><button data-experience-reset>選び直す</button></div>'}}
function apply(n){const c=configs[n]||configs.everyday;document.documentElement.dataset.experience=n;document.body.dataset.experience=n;const q=document.querySelector('[data-how-question]');if(q)q.textContent=c.q;window.MingleDemo?.setQuestions(c.s.slice(0,3).map(d=>d[2]));window.MingleCarousel?.setScenes(c.s);window.MingleCarousel?.reset();const list=document.querySelector('[data-usecases]');if(list)list.innerHTML=c.s.slice(0,5).map(d=>`<article class="usecase"><img src="${d[0]}" alt="${d[1]}で会話する様子" loading="lazy"><div><h3>${d[1]}</h3><p class="eyebrow">${d[3]}</p><p>${d[2]}</p><a href="https://mingle.cards/">Mingleで遊ぶ ↗</a></div></article>`).join('');document.querySelectorAll('[data-experience-choice]').forEach(b=>{const a=b.dataset.experienceChoice===n;b.classList.toggle('is-selected',a);b.setAttribute('aria-pressed',String(a))})}
function choose(v){if(!valid(v))return;try{window.MingleExperienceRouting?.remember(window.localStorage,v,Date.now())}catch(_){}apply(v);const u=window.MingleExperienceRouting?.selectionUrl(location.href,v);if(u)history.replaceState({},'',u)}
window.MingleExperience={configs,apply,resolve:()=>route().experience};document.addEventListener('DOMContentLoaded',()=>{setup();apply(route().experience);document.querySelectorAll('[data-experience-choice]').forEach(b=>b.addEventListener('click',()=>choose(b.dataset.experienceChoice)));document.querySelector('[data-experience-reset]')?.addEventListener('click',()=>{try{window.MingleExperienceRouting?.forget(window.localStorage)}catch(_){}const u=window.MingleExperienceRouting?.resetUrl(location.href);if(u)history.replaceState({},'',u);apply('everyday')})});
})();
